-- Run this entire script in Supabase > SQL Editor > New query.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'resident' check (role in ('admin','resident')), created_at timestamptz not null default now());
create table if not exists public.services (id bigint generated by default as identity primary key, name varchar(150) not null, description text not null, requirements text, office varchar(150), contact varchar(100), is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.announcements (id bigint generated by default as identity primary key, title varchar(200) not null, content text not null, created_at timestamptz not null default now());
create table if not exists public.residents (id bigint generated by default as identity primary key, full_name varchar(150) not null, email varchar(150), phone varchar(50), address varchar(255), created_at timestamptz not null default now());
create table if not exists public.service_requests (id bigint generated by default as identity primary key, resident_name varchar(150) not null, contact varchar(100), service_id bigint not null references public.services(id) on update cascade on delete restrict, purpose text not null, status text not null default 'Pending' check (status in ('Pending','Processing','Completed','Rejected')), created_at timestamptz not null default now());
create or replace function public.is_bayan_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
alter table public.profiles enable row level security; alter table public.services enable row level security; alter table public.announcements enable row level security; alter table public.residents enable row level security; alter table public.service_requests enable row level security;
drop policy if exists "profile self read" on public.profiles; create policy "profile self read" on public.profiles for select to authenticated using (id=auth.uid());
drop policy if exists "public active services read" on public.services; create policy "public active services read" on public.services for select to anon, authenticated using (is_active=true or public.is_bayan_admin());
drop policy if exists "admins manage services" on public.services; create policy "admins manage services" on public.services for all to authenticated using (public.is_bayan_admin()) with check (public.is_bayan_admin());
drop policy if exists "public announcements read" on public.announcements; create policy "public announcements read" on public.announcements for select to anon, authenticated using (true);
drop policy if exists "admins manage announcements" on public.announcements; create policy "admins manage announcements" on public.announcements for all to authenticated using (public.is_bayan_admin()) with check (public.is_bayan_admin());
drop policy if exists "public submit requests" on public.service_requests; create policy "public submit requests" on public.service_requests for insert to anon, authenticated with check (status='Pending');
drop policy if exists "admins manage requests" on public.service_requests; create policy "admins manage requests" on public.service_requests for all to authenticated using (public.is_bayan_admin()) with check (public.is_bayan_admin());
drop policy if exists "admins manage residents" on public.residents; create policy "admins manage residents" on public.residents for all to authenticated using (public.is_bayan_admin()) with check (public.is_bayan_admin());
insert into public.services(name,description,requirements,office,contact) select 'Barangay Clearance','Request a barangay clearance for employment, school, business, and other official purposes.','Valid government-issued ID; proof of residency if required.','Barangay Office','Contact the Barangay Office' where not exists(select 1 from public.services where name='Barangay Clearance');
insert into public.services(name,description,requirements,office,contact) select 'Certificate of Residency','Obtain an official certificate confirming residency within the community.','Valid government-issued ID.','Barangay Office','Contact the Barangay Office' where not exists(select 1 from public.services where name='Certificate of Residency');
insert into public.services(name,description,requirements,office,contact) select 'Community Assistance','Submit a request for available community assistance and support programs.','Valid ID and supporting documents, when applicable.','Community Services Desk','Contact the Community Services Desk' where not exists(select 1 from public.services where name='Community Assistance');
insert into public.announcements(title,content) select 'Welcome to BayanConnect','BayanConnect provides community information and available services in one convenient place.' where not exists(select 1 from public.announcements where title='Welcome to BayanConnect');
-- IMPORTANT: After creating your admin user in Supabase Authentication > Users, copy its UUID and run:
-- insert into public.profiles(id, role) values ('PASTE-AUTH-USER-UUID-HERE','admin');

-- Explicit API privileges (RLS above still decides which rows/actions are allowed).
grant usage on schema public to anon, authenticated;
grant select on public.services, public.announcements to anon, authenticated;
grant insert on public.service_requests to anon, authenticated;
grant select, insert, update, delete on public.services, public.announcements, public.residents, public.service_requests to authenticated;
grant select on public.profiles to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;
